BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the purpose of ''process standardization'' (documented standard operating procedures) in a wet-processing facility?', '["To ensure every operator/shift performs each process step consistently, reducing variation and quality defects across different production runs","Standardization exists purely for legal paperwork with no actual production benefit","Process standardization only applies to office administrative tasks, not actual dyeing/finishing operations","Standard procedures make no difference to consistency since every batch is inherently unique regardless of method"]'::jsonb, 'To ensure every operator/shift performs each process step consistently, reducing variation and quality defects across different production runs', 'Documented, standardized procedures (exact steps, parameters, checks) ensure that regardless of which operator or shift runs a process, it''s executed consistently — directly reducing batch-to-batch variation and the resulting quality defects that inconsistent, ad-hoc practices would cause.', 1, '{"process-standardization"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why might a wet-processing mill invest in an in-house testing lab (strength, colorfastness, shrinkage testing) rather than relying solely on final buyer inspection?', '["In-house testing allows catching problems early (before shipment) and enables faster process correction, reducing costly rejections and rework at a later, more expensive stage","In-house testing has no value since only the buyer''s final inspection results ever matter","In-house labs exist purely for marketing purposes, unrelated to actual product quality","Relying only on buyer inspection is always faster and cheaper than any form of in-house testing"]'::jsonb, 'In-house testing allows catching problems early (before shipment) and enables faster process correction, reducing costly rejections and rework at a later, more expensive stage', 'Testing quality parameters in-house (before shipment) lets a mill identify and correct process problems early, well before a costly late-stage rejection at the buyer''s final inspection — a proactive quality approach that''s generally far cheaper than reactive problem-solving after goods have already shipped.', 2, '{"in-house-testing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''AQL'' (Acceptable Quality Level) commonly used for in textile/garment quality inspection?', '["A statistical sampling standard defining how many defects in a sample size are acceptable before a shipment/batch is considered to have failed inspection","The exact percentage of dye used in a specific recipe","A measure of fabric strength unrelated to any inspection sampling method","The total production capacity of a specific dyeing machine"]'::jsonb, 'A statistical sampling standard defining how many defects in a sample size are acceptable before a shipment/batch is considered to have failed inspection', 'AQL is a widely used statistical sampling system: rather than inspecting every single unit in a large shipment, a defined sample size is inspected, and the number of defects found is compared against an acceptable threshold to decide whether to accept or reject the entire lot.', 1, '{"aql-inspection"}'::text[]);
COMMIT;
